class_name Inventory
extends Node

signal changed

@export var slot_count: int = 20

var slots: Array = []

func _ready() -> void:
	slots.resize(slot_count)

func add_item(item: ItemData, amount: int = 1) -> int:
	# Возвращает, сколько не поместилось.
	for slot in slots:
		if amount == 0:
			break
		if slot != null and slot['item'] == item and slot['count'] < item.max_stack:
			var moved: int = mini(item.max_stack - slot['count'], amount)
			slot['count'] += moved
			amount -= moved
	for i in slots.size():
		if amount == 0:
			break
		if slots[i] == null:
			var moved: int = mini(item.max_stack, amount)
			slots[i] = {'item': item, 'count': moved}
			amount -= moved
	changed.emit()
	return amount

func count_item(item: ItemData) -> int:
	var total: int = 0
	for slot in slots:
		if slot != null and slot['item'] == item:
			total += slot['count']
	return total

func remove_item(item: ItemData, amount: int = 1) -> bool:
	if count_item(item) < amount:
		return false
	for i in slots.size():
		if amount == 0:
			break
		var slot = slots[i]
		if slot != null and slot['item'] == item:
			var taken: int = mini(slot['count'], amount)
			slot['count'] -= taken
			amount -= taken
			if slot['count'] == 0:
				slots[i] = null
	changed.emit()
	return true

# ===== SaveSystem.gd (Project Settings > Globals > Autoload) =====
extends Node

const SAVE_PATH: String = 'user://savegame.json'
const SAVE_VERSION: int = 1

func save_game(data: Dictionary) -> bool:
	var payload: Dictionary = {'version': SAVE_VERSION, 'data': data}
	var file: FileAccess = FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file == null:
		push_error('Не удалось открыть файл сохранения: ' + str(FileAccess.get_open_error()))
		return false
	file.store_string(JSON.stringify(payload, '\t'))
	return true

func has_save() -> bool:
	return FileAccess.file_exists(SAVE_PATH)

func load_game() -> Dictionary:
	if not has_save():
		return {}
	var file: FileAccess = FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		return {}
	var parsed: Variant = JSON.parse_string(file.get_as_text())
	if not (parsed is Dictionary):
		push_warning('Файл сохранения повреждён')
		return {}
	if int(parsed.get('version', 0)) != SAVE_VERSION:
		push_warning('Неизвестная версия сохранения')
		return {}
	return parsed.get('data', {})

# ===== Player.gd (добавить) =====
func get_save_data() -> Dictionary:
	return {
		'position': [global_position.x, global_position.y],
		'health': $HealthComponent.current_health,
	}

func apply_save_data(data: Dictionary) -> void:
	var pos: Array = data.get('position', [global_position.x, global_position.y])
	global_position = Vector2(float(pos[0]), float(pos[1]))
	$HealthComponent.current_health = float(data.get('health', $HealthComponent.max_health))
	$HealthComponent.health_changed.emit($HealthComponent.current_health, $HealthComponent.max_health)

