extends Node

@onready var player: Node = get_tree().get_first_node_in_group('player')

func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed('quick_save'):
		SaveSystem.save_game(player.get_save_data())
	elif event.is_action_pressed('quick_load'):
		var data: Dictionary = SaveSystem.load_game()
		if not data.is_empty():
			player.apply_save_data(data)

extends CharacterBody2D

enum State { CHASE, ATTACK, DEAD }

@export var bullet_scene: PackedScene
@export var base_speed: float = 70.0
@export var attack_cooldown: float = 2.4

@onready var health: HealthComponent = $HealthComponent

var state: State = State.CHASE
var phase: int = 1
var target: Node2D
var _time_left: float = 2.0

func _ready() -> void:
	add_to_group('enemy')
	target = get_tree().get_first_node_in_group('player') as Node2D
	health.health_changed.connect(_on_health_changed)
	health.died.connect(_on_died)

func take_damage(amount: float) -> void:
	health.damage(amount)

func _physics_process(delta: float) -> void:
	match state:
		State.CHASE:
			_chase(delta)
		State.ATTACK:
			velocity = Vector2.ZERO
		State.DEAD:
			return
	move_and_slide()

func _chase(delta: float) -> void:
	if target == null or not is_instance_valid(target):
		velocity = Vector2.ZERO
		return
	var speed: float = base_speed * (1.0 + 0.35 * (phase - 1))
	velocity = global_position.direction_to(target.global_position) * speed
	_time_left -= delta
	if _time_left <= 0.0:
		_attack()

func _attack() -> void:
	state = State.ATTACK
	await get_tree().create_timer(0.5).timeout
	if state == State.DEAD:
		return
	_fire_ring(6 + phase * 4)
	_time_left = attack_cooldown / phase
	state = State.CHASE

func _fire_ring(count: int) -> void:
	for i in count:
		var bullet := bullet_scene.instantiate() as Bullet
		get_tree().current_scene.add_child(bullet)
		bullet.target_group = &'player'
		bullet.global_position = global_position
		bullet.direction = Vector2.RIGHT.rotated(TAU * i / count)

func _on_health_changed(current: float, maximum: float) -> void:
	var ratio: float = current / maximum
	var new_phase: int = 1 if ratio > 0.66 else (2 if ratio > 0.33 else 3)
	if new_phase != phase:
		phase = new_phase

func _on_died() -> void:
	state = State.DEAD
	velocity = Vector2.ZERO
	var tween: Tween = create_tween()
	tween.tween_property(self, 'modulate:a', 0.0, 0.8)
	tween.tween_callback(queue_free)
